  function applyPageLanguage() { if (state.role !== 'buyer' || state.lang === 'English') return; const translations = pageTranslations[state.lang] || {}; const walker = document.createTreeWalker(app, NodeFilter.SHOW_TEXT); const nodes = []; while (walker.nextNode()) nodes.push(walker.currentNode); nodes.forEach(node => { const value = node.nodeValue.trim(); if (translations[value]) node.nodeValue = node.nodeValue.replace(value, translations[value]); }); app.querySelectorAll('input[placeholder], textarea[placeholder]').forEach(field => { const translated = translations[field.getAttribute('placeholder')]; if (translated) field.setAttribute('placeholder', translated); }); }

