  const price = value => money.format(value);
  const esc = value => String(value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char]));
  const getProduct = id => db.products.find(item => item.id === id);
  const cartCount = () => db.cart.reduce((total, line) => total + line.quantity, 0);
  const cartTotal = () => db.cart.reduce((total, line) => { const item = getProduct(line.id); return item ? total + item.price * line.quantity : total; }, 0);
  const categories = () => ['All categories', ...new Set(db.products.map(item => item.category))];
  function toast(message) { const node = document.querySelector('#toast'); node.textContent = message; node.classList.add('show'); clearTimeout(window.toastTimer); window.toastTimer = setTimeout(() => node.classList.remove('show'), 2600); }
  async function localAi(prompt) { const controller = new AbortController(); const timeout = setTimeout(() => controller.abort(), 90000); try { const response = await fetch('http://127.0.0.1:11434/api/generate', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ model: 'qwen2.5:0.5b', prompt, stream: false, options: { temperature: 0.2, num_predict: 120 } }), signal: controller.signal }); if (!response.ok) throw new Error(`Ollama returned ${response.status}`); const data = await response.json(); if (!data.response) throw new Error('Ollama returned no text'); return data.response.trim(); } finally { clearTimeout(timeout); } }
